```php
use Commerz\Facades\Commerz;

$store   = Commerz::stores()->create(new CreateStore(code: 'main', name: 'Main', defaultCurrency: Currency::of('RUB')));
$channel = Commerz::channels()->create(new CreateChannel(
    store: $store->id, code: 'web', name: 'Сайт',
    currencies: [Currency::of('RUB')], locales: ['ru', 'en'], pricesIncludeTax: true,
));

$ctx = CommerceContext::for($channel->id, Currency::of('RUB'), locale: 'ru')
    ->withCustomer(CustomerRef::of('user', '42'));          // группы подтягиваются из CustomerDirectory

Commerz::plugins()->describe();                               // диагностика реестра: ключи, источник, версия
```

`Commerz\Commerz`: `stores(): Stores`, `channels(): Channels`, `plugins(): PluginInspector`, `quotes(): QuotePipeline` (низкоуровневый расчёт для своих сценариев), `sellables(): Sellables`.

```php
use Commerz\Catalog\Facades\Catalog;

Catalog::attributes()->define(new DefineAttribute(
    code: 'material', type: 'enum', label: LocalizedText::of(['ru' => 'Материал']),
    options: ['cotton' => ['ru' => 'Хлопок'], 'linen' => ['ru' => 'Лён']],
    filterable: true,
));
Catalog::attributes()->define(new DefineAttribute(code: 'density', type: 'measure', config: ['dimension' => 'areal_density', 'unit' => 'g/m2'], filterable: true));

$type = Catalog::productTypes()->create(new CreateProductType(
    code: 'apparel', kind: 'physical',
    productAttributes: ['material', 'density'], variantAxes: ['color', 'size'],
));

$product = Catalog::products()->create(new CreateProduct(
    type: $type->id, handle: 'basic-tee', name: LocalizedText::of(['ru' => 'Футболка']),
    attributes: ['material' => 'cotton', 'density' => Measure::of('180', 'g/m2')],
));

$variants = Catalog::variants()->generate(new GenerateVariants(
    product: $product->id,
    axes: ['color' => ['red', 'blue'], 'size' => ['S', 'M']],
    skuPattern: 'TEE-{color}-{size}',
    except: [['color' => 'blue', 'size' => 'S']],                // разреженный набор, не полный декарт
));

Catalog::listings()->publish(new PublishProduct(product: $product->id, channel: $channel->id));

$page = Catalog::products()->list(new ListProducts(
    channel: $channel->id,
    filters: [AttributeFilter::equals('material', 'cotton'), VariantFilter::axes(['color' => 'red', 'size' => 'M'])], // один вариант
    first: 24,
));
```

`Catalog`: `products()`, `variants()`, `attributes()`, `productTypes()`, `categories()`, `listings()`. Каталог регистрирует `SellableProvider` с ключом `variant` → `SellableRef::of('variant', $variantId)` годится в корзину.

```php
use Commerz\Inventory\Facades\Inventory;

$wh   = Inventory::locations()->create(new CreateLocation(code: 'msk-1', name: 'Москва-1', kind: LocationKind::Warehouse));
$item = Inventory::items()->create(new CreateStockItem(sku: 'TEE-RED-M', unit: 'pcs'));
Inventory::items()->link(new LinkSellable(sellable: SellableRef::of('variant', $v->id), item: $item->id, quantityPerUnit: 1));
Inventory::sources()->assign(new AssignSource(channel: $channel->id, location: $wh->id, priority: 10));

Inventory::stock()->receive(new ReceiveStock(item: $item->id, location: $wh->id, quantity: 50,
    reason: 'purchase', reference: 'po:123', idempotencyKey: IdempotencyKey::of('po:123:line:1')));
Inventory::stock()->adjust(new AdjustStock(item: $item->id, location: $wh->id, delta: -2, reason: 'damage'));

$answer = Inventory::availability()->check(new CheckAvailability($channel->id, [SellableRef::of('variant', $v->id) => 3]));

$r = Inventory::reservations()->reserve(new ReserveStock(
    demand: 'order:01J…:line:1', channel: $channel->id,
    sellable: SellableRef::of('variant', $v->id), quantity: 3, expiresAt: null,
));                                                           // InsufficientStock при нехватке — атомарно
Inventory::reservations()->consume(new ConsumeReservation($r->id, quantity: 3, reference: 'fulfillment:…')); // движение sale
Inventory::transfers()->dispatch(new DispatchTransfer(from: $wh->id, to: $pvz->id, lines: [[$item->id, 5]]));
```

`Inventory`: `locations()`, `items()`, `sources()`, `stock()` (receive/adjust/count/levels), `reservations()`, `transfers()`, `availability()`, `movements()` (журнал, только чтение).

```php
use Commerz\Pricing\Facades\Pricing;

$list = Pricing::priceLists()->create(new CreatePriceList(code: 'retail', currency: Currency::of('RUB'), channels: [$channel->id]));
Pricing::prices()->set(new SetPrice(
    priceList: $list->id, sellable: SellableRef::of('variant', $v->id),
    amount: Money::of('1990.00', 'RUB'), compareAt: Money::of('2490.00', 'RUB'),
    minQuantity: 1, customerGroup: null, validFrom: null, validUntil: null,
));
Pricing::taxes()->defineClass(new DefineTaxClass(code: 'standard'));
Pricing::taxes()->setRate(new SetTaxRate(taxClass: 'standard', zone: 'RU', rateBp: 2000));

$price = Pricing::prices()->resolve(new ResolvePrice(SellableRef::of('variant', $v->id), quantity: 2, context: $ctx)); // ResolvedPrice + причина выбора
```

```php
use Commerz\Promotions\Facades\Promotions;

$promo = Promotions::promotions()->create(new CreatePromotion(
    code: 'autumn-10', name: 'Осень −10%', channels: [$channel->id],
    activator: 'coupon', stacking: Stacking::Stackable, priority: 100,
    conditions: [new RuleSpec('cart.subtotal_at_least', ['amount' => Money::of('3000.00', 'RUB')])],
    effects:    [new RuleSpec('order.percent_off', ['rateBp' => 1000])],
    limits: new UsageLimits(total: 1000, perCustomer: 1), budget: Money::of('500000.00', 'RUB'),
    startsAt: $from, endsAt: $to,
));
Promotions::coupons()->generate(new GenerateCoupons(promotion: $promo->id, count: 500, pattern: 'AUT-####-####'));
Promotions::coupons()->create(new CreateCoupon(promotion: $promo->id, code: 'AUTUMN', usageLimit: 1000));

$explain = Promotions::promotions()->explain(new ExplainPromotions($quoteInput)); // почему применилась / не применилась
```

Код, введённый в корзину, — это лишь «предъявленный код» в `QuoteInput`; расход лимита происходит только при размещении заказа.

```php
use Commerz\Shipping\Facades\Shipping;

$zone = Shipping::zones()->create(new CreateZone(code: 'msk', name: 'Москва', match: ZoneMatch::regions(['RU-MOW'])));
Shipping::methods()->create(new CreateMethod(
    code: 'courier', name: LocalizedText::of(['ru' => 'Курьер']), zones: [$zone->id], channels: [$channel->id],
    rate: new RuleSpec('weight_table', ['steps' => [[1000, '300.00'], [5000, '500.00']], 'currency' => 'RUB']),
    carrier: 'manual',
));

$options = Shipping::options()->list(new DeliveryRequest($ctx, destination: $address, parcel: $parcel)); // list<DeliveryOption>
```

```php
use Commerz\Sales\Facades\Sales;

$cart = Sales::carts()->create(new CreateCart($ctx));
Sales::carts()->addLine(new AddCartLine($cart->id, SellableRef::of('variant', $v->id), quantity: 2));
Sales::carts()->enterCode(new EnterCode($cart->id, 'AUTUMN'));
Sales::carts()->setAddress(new SetCartAddress($cart->id, AddressRole::Shipping, $address));
Sales::carts()->selectDelivery(new SelectDelivery($cart->id, method: 'courier'));

$quote = Sales::carts()->quote($cart->id);           // QuoteResult: строки, корректировки с объяснениями, налоги, итоги

$order = Sales::checkout()->place(new PlaceOrder(
    cart: $cart->id, idempotencyKey: IdempotencyKey::of($request->header('Idempotency-Key')),
    expectedTotal: $quote->total,                    // защита от изменения цены между показом и оплатой
));                                                  // одна транзакция: заказ-снимок + резерв + расход лимитов + outbox

$payment = Sales::payments()->initiate(new InitiatePayment($order->id, gateway: 'yookassa', amount: $order->total)); // после коммита
Sales::payments()->recordEvent(new RecordPaymentEvent(gateway: 'yookassa', externalId: $evt->id, type: PaymentEventType::Captured, amount: …)); // webhook, дедуп

Sales::fulfillments()->create(new CreateFulfillment($order->id, lines: [[$lineId, 2]], location: $wh->id)); // consume резерва
Sales::fulfillments()->ship(new ShipFulfillment($fulfillmentId, carrier: 'manual', tracking: 'RB123'));
Sales::orders()->cancel(new CancelOrder($order->id, reason: 'customer'));     // release резервов, возврат лимитов по политике
Sales::returns()->request(new RequestReturn($order->id, lines: [[$lineId, 1]], reason: 'defect'));
Sales::returns()->receive(new ReceiveReturn($returnId, restock: [[$lineId, 0]]));  // приёмка ≠ возврат на сток
Sales::refunds()->issue(new IssueRefund($order->id, amount: Money::of('1990.00', 'RUB'), gateway: 'yookassa'));

// CRM: заказ, созданный менеджером, без корзины покупателя
Sales::orders()->draft(new DraftOrder($ctx, lines: [new DraftLine(SellableRef::of('crm.service', '77'), quantity: 1)]));
```

Состояния независимы: `OrderState` (`draft → placed → completed | cancelled`), `PaymentState` (`unpaid → authorized → partially_paid → paid → partially_refunded → refunded`), `FulfillmentState` (`unfulfilled → partially_fulfilled → fulfilled → partially_returned → returned`).

CRM ставит `axiomasoft/commerz` + `axiomasoft/commerz-sales` (+ `commerz-promotions` по желанию):

```php
final class CrmServiceSellables implements SellableProvider          // #[Spi(Implement)]
{
    public function key(): string { return 'crm.service'; }
    public function resolve(array $refs, CommerceContext $context): array   // list<SellableSnapshot>
    { /* читает услуги CRM; basePrice из тарифа; kind Service; requiresShipping false */ }
}

final class CrmPlugin implements CommerzPlugin {
    public function manifest(): PluginManifest { return new PluginManifest(id: 'flex.crm-commerce', version: '1.0.0'); }
    public function register(PluginRegistrar $r): void {
        $r->sellableProvider(CrmServiceSellables::class);
    }
}
// config/commerz.php: 'stock' => 'unlimited', 'customers' => CrmCustomerDirectory::class
```

Без пакетов catalog/inventory/pricing: цена берётся из `SellableSnapshot::$basePrice` (дефолтный `PriceResolver` ядра), остатки — `UnlimitedStock` (явно выбран в конфиге, не молчаливый дефолт).

```php
#[Spi(kind: SpiKind::Implement, since: '0.1')]
interface PromotionEffect
{
    public function key(): string;                                   // 'acme.every_third_free'
    public function configVersion(): int;
    public function decodeConfig(array $raw, int $version): object;  // валидирует и апгрейдит конфиг
    /** @return list<AdjustmentCandidate> */
    public function apply(object $config, PromotionTarget $target): array;  // чистая функция
}

final class AcmePlugin implements CommerzPlugin
{
    public function manifest(): PluginManifest
    { return new PluginManifest(id: 'acme.promos', version: '1.2.0', requires: ['commerz.promotions']); }

    public function register(PluginRegistrar $r): void
    { $r->contribute('promotion_effect', new EveryThirdFree()); }
}
